  "Quotation": "報價單",
  "Sales Order": "銷售訂單",
  "Delivery Note": "出貨單",
  "Sales Invoice": "銷售發票",
  "Purchase Order": "採購單",
  "Purchase Receipt": "採購收貨單",
  "Purchase Invoice": "進貨發票",
  "Stock Entry": "庫存異動單",
  "Work Order": "製令",
  "Job Card": "工作卡"
} %}
{% set table_fields = {
  "Quotation": "items", "Sales Order": "items", "Delivery Note": "items",
  "Sales Invoice": "items", "Purchase Order": "items", "Purchase Receipt": "items",
  "Purchase Invoice": "items", "Stock Entry": "items", "Work Order": "required_items",
  "Job Card": "items"
} %}
{% set table_field = table_fields.get(doc.doctype, "items") %}
{% set child_rows = doc.get(table_field) or [] %}
{% set child_doctype = frappe.get_meta(doc.doctype).get_field(table_field).options %}
{% set child_meta = frappe.get_meta(child_doctype) %}
{% set column_count = 1 %}
{% if child_meta.has_field("item_code") %}{% set column_count = column_count + 1 %}{% endif %}
{% if child_meta.has_field("operation") %}{% set column_count = column_count + 1 %}{% endif %}
{% if child_meta.has_field("description") or child_meta.has_field("item_name") %}{% set column_count = column_count + 1 %}{% endif %}
{% if child_meta.has_field("qty") or child_meta.has_field("required_qty") %}{% set column_count = column_count + 1 %}{% endif %}
{% if child_meta.has_field("uom") %}{% set column_count = column_count + 1 %}{% endif %}
{% if child_meta.has_field("rate") or child_meta.has_field("basic_rate") %}{% set column_count = column_count + 1 %}{% endif %}
{% if child_meta.has_field("amount") %}{% set column_count = column_count + 1 %}{% endif %}
{% if child_meta.has_field("s_warehouse") %}{% set column_count = column_count + 1 %}{% endif %}
{% if child_meta.has_field("t_warehouse") %}{% set column_count = column_count + 1 %}{% endif %}
{% if child_meta.has_field("workstation") %}{% set column_count = column_count + 1 %}{% endif %}
{% set company = frappe.get_cached_doc("Company", doc.company) if doc.company else None %}
{% set logo = company.company_logo if company and company.company_logo else "/assets/mmold_hub/images/mmold-hub-logo.png" %}
{% set currency = doc.currency if doc.currency else "TWD" %}
{% set party_label = "客戶" if doc.get("customer") else ("供應商" if doc.get("supplier") else ("製成品" if doc.get("production_item") else ("異動類型" if doc.get("stock_entry_type") else "單據類型"))) %}
{% set party_value = doc.get("customer_name") or doc.get("customer") or doc.get("supplier_name") or doc.get("supplier") or doc.get("production_item") or doc.get("stock_entry_type") or print_titles.get(doc.doctype, doc.doctype) %}
{% set date_field = "transaction_date" if doc.meta.has_field("transaction_date") else ("posting_date" if doc.meta.has_field("posting_date") else ("planned_start_date" if doc.meta.has_field("planned_start_date") else None)) %}
